import{_ as t,o as n,c as r,a0 as a}from"./chunks/framework.DJ-9CPBN.js";const p=JSON.parse('{"title":"Auditerra Technical Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function i(s,e,d,l,c,h){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="auditerra-technical-documentation" tabindex="-1">Auditerra Technical Documentation <a class="header-anchor" href="#auditerra-technical-documentation" aria-label="Permalink to &quot;Auditerra Technical Documentation&quot;">​</a></h1><p>Welcome to the official technical documentation for the Auditerra platform.</p><p>This documentation serves as the central repository for all technical knowledge regarding the design, implementation, deployment, and maintenance of the Auditerra system. Whether you are a new developer setting up your local environment, an architect reviewing the system design, or a QA engineer validating new features, you will find the specific guides and references you need here.</p><h2 id="audience" tabindex="-1">Audience <a class="header-anchor" href="#audience" aria-label="Permalink to &quot;Audience&quot;">​</a></h2><p>This documentation is designed for:</p><ul><li><p><strong>Developers</strong> integrating with or extending the Auditerra system. You will find API references, database schemas, and code organization guides to help you understand how the system works and where to make changes.</p></li><li><p><strong>DevOps and IT teams</strong> managing production infrastructure. Deployment guides, environment configuration, and monitoring setup are covered to ensure smooth operations.</p></li><li><p><strong>Project Stakeholders</strong> involved in technical review and system oversight. Architecture overviews and security documentation provide the context needed for informed decision-making.</p></li><li><p><strong>QA Engineers</strong> validating new features and maintaining quality. Testing guides and troubleshooting sections help ensure the system remains stable and reliable.</p></li></ul><h2 id="how-to-use-this-documentation" tabindex="-1">How to Use This Documentation <a class="header-anchor" href="#how-to-use-this-documentation" aria-label="Permalink to &quot;How to Use This Documentation&quot;">​</a></h2><p>The documentation is organized to support different workflows depending on your role and immediate needs.</p><h3 id="new-team-members" tabindex="-1">New Team Members <a class="header-anchor" href="#new-team-members" aria-label="Permalink to &quot;New Team Members&quot;">​</a></h3><p>Start with the <strong>Getting Started</strong> guide to set up your development environment and run the application locally. Then explore the <strong>Architecture</strong> section to understand how the system fits together. The <strong>Developer Guide</strong> provides detailed information on code standards and contribution workflows.</p><h3 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h3><p>For implementation work, the <strong>API Reference</strong> provides detailed endpoint documentation including request and response schemas. The <strong>Database Schema</strong> section explains the data model and relationships. <strong>Frontend</strong> documentation covers both the web application and the offline-first mobile PWA.</p><h3 id="devops-engineers" tabindex="-1">DevOps Engineers <a class="header-anchor" href="#devops-engineers" aria-label="Permalink to &quot;DevOps Engineers&quot;">​</a></h3><p>The <strong>Deployment</strong> section covers Heroku and Vercel configuration, environment variables, and monitoring. Security documentation explains authentication, authorization, and data protection.</p><h3 id="qa-engineers" tabindex="-1">QA Engineers <a class="header-anchor" href="#qa-engineers" aria-label="Permalink to &quot;QA Engineers&quot;">​</a></h3><p>The <strong>Testing</strong> guide covers how to run unit tests, integration tests, and API tests. The <strong>Troubleshooting</strong> section documents common issues and their resolutions.</p><h2 id="documentation-structure" tabindex="-1">Documentation Structure <a class="header-anchor" href="#documentation-structure" aria-label="Permalink to &quot;Documentation Structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>What You Will Find</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Product vision, problem statement, key features</td></tr><tr><td><strong>Getting Started</strong></td><td>Prerequisites, installation, environment setup, first run</td></tr><tr><td><strong>Architecture</strong></td><td>System components, data flow, technology decisions</td></tr><tr><td><strong>API Reference</strong></td><td>All backend endpoints with examples and schemas</td></tr><tr><td><strong>Frontend Web</strong></td><td>Next.js application structure and components</td></tr><tr><td><strong>Frontend Mobile</strong></td><td>PWA setup, offline-first architecture, IndexedDB</td></tr><tr><td><strong>Security</strong></td><td>Authentication, authorization, data protection</td></tr><tr><td><strong>AI Module</strong></td><td>Gemini integration, RAG processing, prompt engineering</td></tr><tr><td><strong>Deployment</strong></td><td>Heroku backend, Vercel frontend, CI/CD pipeline</td></tr><tr><td><strong>Developer Guide</strong></td><td>Code standards, commit conventions, PR process</td></tr><tr><td><strong>Testing</strong></td><td>Test strategy, running tests, troubleshooting</td></tr></tbody></table><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><p>Before diving into the technical details, it helps to understand the key concepts that shape Auditerra.</p><h3 id="offline-first-design" tabindex="-1">Offline-First Design <a class="header-anchor" href="#offline-first-design" aria-label="Permalink to &quot;Offline-First Design&quot;">​</a></h3><p>Field experts often work in areas with unreliable or no internet connectivity. The system is designed to function offline, storing data locally in IndexedDB and synchronizing automatically when connectivity is restored. This ensures that work continues uninterrupted regardless of network conditions.</p><h3 id="human-verified-data" tabindex="-1">Human-Verified Data <a class="header-anchor" href="#human-verified-data" aria-label="Permalink to &quot;Human-Verified Data&quot;">​</a></h3><p>Unlike satellite-based monitoring, Auditerra relies on on-the-ground verification. Every data point is collected by a trained expert who physically visits the farm. The security handshake system ensures that experts are actually present at the reported location, preventing fraud.</p><h3 id="audit-ready-workflow" tabindex="-1">Audit-Ready Workflow <a class="header-anchor" href="#audit-ready-workflow" aria-label="Permalink to &quot;Audit-Ready Workflow&quot;">​</a></h3><p>All actions in the system are tracked and auditable. The 60-day audit loop enforces re-testing to measure biological survival rather than just planting speed. This creates a verifiable impact record that can be presented to funders and stakeholders.</p><h3 id="role-based-access" tabindex="-1">Role-Based Access <a class="header-anchor" href="#role-based-access" aria-label="Permalink to &quot;Role-Based Access&quot;">​</a></h3><p>The system serves three distinct user personas with different needs and permissions:</p><ul><li><strong>Farmers</strong> report issues via USSD</li><li><strong>Experts</strong> collect diagnostic data and receive assignments</li><li><strong>Supervisors</strong> monitor progress and manage operations</li></ul><p>Each role has specific access controls and interfaces tailored to their workflow.</p><h2 id="quick-links" tabindex="-1">Quick Links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick Links&quot;">​</a></h2><ul><li><a href="/Auditerra-Technical-Documentation-/architecture/overview.html">Architecture</a> : Understand the system design</li><li><a href="/Auditerra-Technical-Documentation-/api/overview.html">API Reference</a> : Explore the endpoints</li><li><a href="/Auditerra-Technical-Documentation-/deployment/overview.html">Deployment</a> : Production setup</li></ul><hr><p><em>Built for Kenya&#39;s land restoration</em></p>',34)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
